import{c as a,Q as e,j as i,m as l}from"./chunks/framework.DOi4mjdC.js";const S=JSON.parse('{"title":"SoftmaxFlashV3 Tiling接口","description":"","frontmatter":{},"headers":[{"level":1,"title":"SoftmaxFlashV3 Tiling接口","slug":"softmaxflashv3-tiling接口"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"}],"relativePath":"api/SIMD-API/高阶API/激活函数/SoftMax接口/SoftmaxFlashV3-Tiling接口.md","filePath":"api/SIMD-API/高阶API/激活函数/SoftMax接口/SoftmaxFlashV3-Tiling接口.md"}'),s={name:"api/SIMD-API/高阶API/激活函数/SoftMax接口/SoftmaxFlashV3-Tiling接口.md"};function d(o,t,n,r,p,h){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="softmaxflashv3-tiling接口" tabindex="-1">SoftmaxFlashV3 Tiling接口 <a class="header-anchor" href="#softmaxflashv3-tiling接口" aria-label="Permalink to &quot;SoftmaxFlashV3 Tiling接口&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>用于获取SoftmaxFlashV3接口所需的Tiling参数。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>获取Kernel接口计算所需最小/最大临时空间的接口</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetSoftMaxFlashV3MaxMinTmpSize(const ge::Shape&amp; srcShape, const uint32_t dataTypeSize1, const uint32_t dataTypeSize2, uint32_t&amp; maxValue, uint32_t&amp; minValue, const bool isUpdate, const bool isBasicBlock = false)</span></span></code></pre></div></li><li><p>Tiling计算接口</p><ul><li><p>AscendC::optiling命名空间下的计算接口</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void SoftMaxFlashV3TilingFunc(const ge::Shape&amp; srcShape, const uint32_t dataTypeSize1, const uint32_t dataTypeSize2,const uint32_t localWorkSpaceSize, optiling::SoftMaxTiling&amp; softmaxFlashV3Tiling, const bool isUpdate,const bool isBasicBlock = false)</span></span></code></pre></div></li><li><p>AscendC命名空间下的计算接口</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void SoftMaxFlashV3TilingFunc(const ge::Shape&amp; srcShape, const uint32_t dataTypeSize1, const uint32_t dataTypeSize2,const uint32_t localWorkSpaceSize, AscendC::tiling::SoftMaxTiling&amp; softmaxFlashV3Tiling, const bool isUpdate,const bool isBasicBlock = false)</span></span></code></pre></div></li></ul></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> GetSoftMaxFlashV3MaxMinTmpSize接口参数列表</p><table tabindex="0"><thead><tr><th>接口</th><th>输入/输出</th><th>功能</th></tr></thead><tbody><tr><td>srcShape</td><td>输入</td><td>输入srcTensor的shape信息。</td></tr><tr><td>dataTypeSize1</td><td>输入</td><td>输入srcTensor的数据类型大小，即对应SoftMaxFlashV3 Kernel函数中模板参数T的数据类型大小。当前模板参数T仅支持half类型，故此参数只支持取值为2。</td></tr><tr><td>dataTypeSize2</td><td>输入</td><td>输入inMeanTensor、inExpSumTensor、inMaxTensor的数据类型大小，即对应SoftMaxFlashV3 Kernel函数中模板参数U的数据类型大小。当前模板参数U仅支持float类型，故此参数只支持取值为4。</td></tr><tr><td>maxValue</td><td>输出</td><td>SoftMaxFlashV3接口能完成计算所需的最大临时空间大小，超出该值的空间不会被该接口使用。在最小临时空间-最大临时空间范围内，随着临时空间增大，kernel侧接口计算性能会有一定程度的优化提升。为了达到更好的性能，开发者可以根据实际的内存使用情况进行空间预留/申请。最大空间大小为0表示计算不需要临时空间。 说明： maxValue仅作为参考值，有可能大于Unified Buffer剩余空间的大小，该场景下，开发者需要根据Unified Buffer剩余空间的大小来选取合适的临时空间大小。</td></tr><tr><td>minValue</td><td>输出</td><td>SoftMaxFlashV3接口能完成计算所需最小临时空间大小。为保证功能正确，接口计算时预留/申请的临时空间不能小于该数值。最小空间大小为0表示计算不需要临时空间。</td></tr><tr><td>isUpdate</td><td>输入</td><td>是否使能SoftMaxFlashV3 update为true的公式计算。该参数取值与SoftmaxFlashV3 Kernel接口的模板参数isUpdate保持一致。</td></tr><tr><td>isBasicBlock</td><td>输入</td><td>预留参数，暂未启用，必须使用默认值false。</td></tr></tbody></table><p><strong>表 2</strong> SoftMaxFlashV3TilingFunc接口参数列表</p><table tabindex="0"><thead><tr><th>接口</th><th>输入/输出</th><th>功能</th></tr></thead><tbody><tr><td>srcShape</td><td>输入</td><td>输入srcTensor的shape信息。</td></tr><tr><td>dataTypeSize1</td><td>输入</td><td>输入srcTensor的数据类型大小，即对应SoftMaxFlashV3 Kernel函数中模板参数T的数据类型大小。当前模板参数T仅支持half类型，故此参数只支持取值为2。</td></tr><tr><td>dataTypeSize2</td><td>输入</td><td>输入inMeanTensor、inExpSumTensor、inMaxTensor的数据类型大小，即对应SoftMaxFlashV3 Kernel函数中模板参数U的数据类型大小。当前模板参数U仅支持float类型，故此参数只支持取值为4。</td></tr><tr><td>localWorkSpaceSize</td><td>输入</td><td>剩余的可供SoftmaxFlashV3接口计算的空间大小。localWorkSpaceSize的取值必须大于GetSoftMaxFlashV3MaxMinTmpSize接口返回的计算所需的最小临时空间大小。</td></tr><tr><td>isUpdate</td><td>输入</td><td>是否使能SoftMaxFlashV3 update为true的公式计算。与SoftmaxFlashV3 Kernel接口的模板参数isUpdate保持一致。</td></tr><tr><td>isBasicBlock</td><td>输入</td><td>预留参数，暂未启用，必须使用默认值false。</td></tr><tr><td>softmaxFlashV3Tiling</td><td>输出</td><td>输出SoftMaxFlashV3接口所需的Tiling信息，支持optiling::SoftMaxTiling形式入参和AscendC::tiling::SoftMaxTiling形式入参。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p>',14)])])}const f=a(s,[["render",d]]);export{S as __pageData,f as default};
